const norm = (r: any) => Array.isArray(r) ? r : (r?.items ?? r?.issues ?? r?.comments ?? r?.data ?? []);
const login = (c: any) => c?.user?.login ?? c?.author?.login ?? c?.user ?? c?.login ?? null;

let issues: any[] = [];
for (let page = 1; page < 100; page++) {
  const batch = norm(await tools.list_issues({ repo: "acme/web", state: "open", label: "perf", page }));
  if (batch.length === 0) break;
  issues.push(...batch);
  if (batch.length < 50) break;
}
// keep only issues that really carry the label and are open
issues = issues.filter((i: any) => {
  const labels = (i.labels ?? []).map((l: any) => (typeof l === "string" ? l : l?.name));
  return (i.state ?? "open") === "open" && labels.includes("perf");
});

const counts: Record<string, Set<number>> = {};
const seenNumbers = new Set<number>();
for (const iss of issues) {
  const num = iss.number;
  if (seenNumbers.has(num)) continue;
  seenNumbers.add(num);
  for (let page = 1; page < 100; page++) {
    const batch = norm(await tools.list_comments({ repo: "acme/web", number: num, page }));
    for (const c of batch) {
      const who = login(c);
      if (!who) continue;
      (counts[who] ??= new Set()).add(num);
    }
    if (batch.length < 50) break;
  }
}

const result = Object.entries(counts)
  .filter(([, s]) => s.size >= 4)
  .map(([u]) => u)
  .sort();

return { issueCount: issues.length, issueNumbers: [...seenNumbers], result, all: Object.fromEntries(Object.entries(counts).map(([u, s]) => [u, s.size])) };
